    async function getDynamicFile() {
        try {
            const result = await AsyncStorage.getItem('dynamicFile');
            if (result) {
                return JSON.parse(result);
            }
        } catch (error) {
            console.error('Ошибка при получении динамического файла:', error);
        }
    }

    getDynamicFile().then(data => {
        console.log('Динамический файл:', data);
    }).catch(error => {
        console.error('Ошибка:', error);
    });
}

export default getDynamicFile;
